function obterColaboradores(){const e=localStorage.getItem("colaboradores");return e?JSON.parse(e):[]}function salvarCadastro(e){const a={nome:e.nome.value,email:e.email.value,nascimento:e.nascimento.value,cpf:e.cpf.value,telefone:e.telefone.value,cep:e.cep.value,endereco:e.endereco.value,cidade:e.cidade.value,estado:e.estado.value,interesse:e.interesse.value},o=obterColaboradores();o.push(a),localStorage.setItem("colaboradores",JSON.stringify(o))}